using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.IO;

public class RemoveCheckerboard
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        string[] paths = { "Assets/Herbal/JamuIcon.png", "Assets/Herbal/SpiceIcon.png" };
        foreach (var path in paths)
        {
            Texture2D tex = new Texture2D(2, 2);
            byte[] fileData = File.ReadAllBytes(path);
            tex.LoadImage(fileData);

            Color[] pixels = tex.GetPixels();
            int width = tex.width;
            int height = tex.height;

            // Ambil sample warna checkerboard dari pojok (0,0) dan (1,0)
            Color bg1 = pixels[0];
            Color bg2 = pixels[1];

            // Kita asumsikan background itu abu-abu (r~g~b) dan match salah satu dari 2 warna bg
            for (int i = 0; i < pixels.Length; i++)
            {
                Color c = pixels[i];
                bool isGrey = Mathf.Abs(c.r - c.g) < 0.1f && Mathf.Abs(c.g - c.b) < 0.1f;

                if (isGrey)
                {
                    float dist1 = Vector4.Distance(c, bg1);
                    float dist2 = Vector4.Distance(c, bg2);

                    // Kalau warnanya mirip dengan checkerboard pattern, jadikan transparan
                    if (dist1 < 0.15f || dist2 < 0.15f || (c.r > 0.4f && c.r < 0.9f && isGrey))
                    {
                        pixels[i] = new Color(c.r, c.g, c.b, 0f);
                    }
                }
            }

            tex.SetPixels(pixels);
            tex.Apply();

            byte[] newBytes = tex.EncodeToPNG();
            File.WriteAllBytes(path, newBytes);
            sb.AppendLine("[OK] Background dihapus untuk: " + path);
        }

        AssetDatabase.Refresh();
        return sb.ToString();
    }
}
